import re

def parse_to_pixels(line):
    """Return list of 0/1 for each 2-char pixel position, using 'H' for half-pixels"""
    pixels = []
    i = 0
    while i < len(line):
        if line[i] == '\x1b':
            j = i
            while j < len(line) and line[j] != 'm':
                j += 1
            esc = line[i:j+1]
            i = j + 1
            k = i
            while k < len(line) and line[k] != '\x1b':
                k += 1
            content = line[i:k]
            is_on = '42' in esc
            for pos in range(0, len(content), 2):
                if pos+1 < len(content):
                    pixels.append(1 if is_on else 0)
                elif pos < len(content):
                    pixels.append(-1)
            i = k
        else:
            k = i
            while k < len(line) and line[k] != '\x1b':
                k += 1
            content = line[i:k]
            for pos in range(0, len(content), 2):
                if pos+1 < len(content):
                    pixels.append(0)
                elif pos < len(content):
                    pixels.append(-1)
            i = k
    return pixels

cap1_lines = open('/tmp/cap1e.txt').readlines()
cap2_lines = open('/tmp/cap2e.txt').readlines()

# Let me print the raw lines to understand structure
print("CAP1 raw:")
for i in range(1, 7):
    if i < len(cap1_lines):
        line = cap1_lines[i]
        # Remove escape codes for viewing
        clean = re.sub(r'\x1b\[\d+m', '', line).rstrip('\n')
        print(f"  Row {i}: '{clean}'")

print("\nPixel analysis of CAP1:")
for i in range(1, 6):
    line = cap1_lines[i].rstrip('\n')
    px = parse_to_pixels(line)
    print(f"  Row {i}: len={len(px)} pixels: {px}")

