import re

def parse_segments(line):
    """Parse a line into segments of (type, length)"""
    segments = []
    i = 0
    while i < len(line):
        if line[i] == '\x1b':
            j = i
            while j < len(line) and line[j] != 'm':
                j += 1
            esc = line[i:j+1]
            i = j + 1
            k = i
            while k < len(line) and line[k] != '\x1b':
                k += 1
            content = line[i:k]
            is_on = '42' in esc
            if content:
                segments.append(('ON' if is_on else 'OFF', len(content)))
            i = k
        else:
            k = i
            while k < len(line) and line[k] != '\x1b':
                k += 1
            content = line[i:k]
            if content:
                segments.append(('OFF', len(content)))
            i = k
    return segments

def get_row_bitmap(segments):
    """Convert segments to a bitmap string"""
    result = []
    for typ, length in segments:
        if typ == 'ON':
            result.extend(['1'] * length)
        else:
            result.extend(['0'] * length)
    return ''.join(result)

# Load all captures
captures = {}
for t in range(1, 16):
    fname = f'/tmp/cap_t{t}.txt'
    try:
        with open(fname) as f:
            lines = f.readlines()
        clock_rows = []
        for i in range(1, 6):
            if i < len(lines):
                segs = parse_segments(lines[i].rstrip('\n'))
                bitmap = get_row_bitmap(segs)
                clock_rows.append(bitmap)
        captures[t] = clock_rows
    except Exception as e:
        print(f"Error loading {fname}: {e}")

# Find when the display changed
prev = None
for t in range(1, 16):
    curr = captures[t]
    if curr != prev:
        print(f"\nTime t={t}: CHANGED")
        for row_idx, bitmap in enumerate(curr):
            print(f"  Row {row_idx+1}: {bitmap}")
    else:
        print(f"Time t={t}: same as previous")
    prev = curr

