            content = line[i:k]
            if content:
                segments.append(('OFF', len(content)))
            i = k
    return segments

def get_row_bitmap(segments):
    result = []
    for typ, length in segments:
        if typ == 'ON':
            result.extend(['1'] * length)
        else:
            result.extend(['0'] * length)
    return ''.join(result)

# Based on the analysis:
# The clock bitmap row has total 50-52 chars
# Looking at the first 26 chars (common across all times in our 15s window):
# These are: H1(8)+H2(8)+colon(2)+M1(8) = 26 chars... starting from col 1
# Plus 5 leading chars (col 0 background + H1 leading OFFs)

# Wait, let me see what's common in all captures:
captures = {}
for t in range(1, 16):
    fname = f'/tmp/cap_t{t}.txt'
    with open(fname) as f:
        lines = f.readlines()
    clock_rows = []
    for i in range(1, 6):
        if i < len(lines):
            segs = parse_segments(lines[i].rstrip('\n'))
            bitmap = get_row_bitmap(segs)
            clock_rows.append(bitmap)
    captures[t] = clock_rows

# Find common prefix across all captures for each row
for row_idx in range(5):
    bitmaps = [captures[t][row_idx] for t in range(1, 16) if row_idx < len(captures[t])]
    # Find longest common prefix
    if not bitmaps:
        continue
    min_len = min(len(b) for b in bitmaps)
    common = 0
    for i in range(min_len):
        if len(set(b[i] for b in bitmaps)) == 1:
            common = i + 1
        else:
            break
    print(f"Row {row_idx+1}: common prefix length = {common}")
    print(f"  Common: {bitmaps[0][:common]}")
    print(f"  Variant: {bitmaps[0][common:]}")
    # Show unique variants
    suffixes = {}
    for t in range(1, 16):
        if row_idx < len(captures[t]):
            suffix = captures[t][row_idx][common:]
            suffixes[t] = suffix
    unique_suffixes = sorted(set(suffixes.values()))
    print(f"  Unique suffixes ({len(unique_suffixes)}):")
    for s in unique_suffixes:
        times = [t for t in suffixes if suffixes[t] == s]
        print(f"    {s} at t={times}")

