    draw_digit(win, h / 10, row, offset + 1, cp, bold);
    draw_digit(win, h % 10, row, offset + 1 + DIGIT_WIDTH + GAP_WIDTH, cp, bold);

    /* Draw colon between hours and minutes */
    draw_colon(win, row, offset + 1 + DIGIT_WIDTH * 2 + GAP_WIDTH, cp, bold, colon_visible);

    /* Draw minutes */
    draw_digit(win, m / 10, row, offset + 1 + DIGIT_WIDTH * 2 + GAP_WIDTH + COLON_WIDTH, cp, bold);
    draw_digit(win, m % 10, row, offset + 1 + DIGIT_WIDTH * 3 + GAP_WIDTH * 2 + COLON_WIDTH, cp, bold);

