        /* Draw colon between minutes and seconds */
        draw_colon(win, row, offset + 1 + DIGIT_WIDTH * 4 + GAP_WIDTH * 2 + COLON_WIDTH, cp, bold, colon_visible);

        /* Draw seconds */
        draw_digit(win, s / 10, row, offset + 1 + DIGIT_WIDTH * 4 + GAP_WIDTH * 2 + COLON_WIDTH * 2, cp, bold);
