        return 52;
    else
        return 33; /* 1+6+1+6+6+6+1+6 = 33? Let me recalculate: 1+D+gap+D+colon+D+gap+D = 1+6+1+6+6+6+1+6=33 */
}

static void draw_date(WINDOW *win, int row, int col, const char *date_str, int color_pair) {
    int date_len = strlen(date_str);
    int date_col;
    int disp_width = get_display_width();

    /* Center date under clock */
    date_col = col + (disp_width - date_len) / 2;

    wmove(win, row, date_col);
    wattron(win, COLOR_PAIR(color_pair));
    waddstr(win, date_str);
    wattroff(win, COLOR_PAIR(color_pair));
}

static int get_box_height(void) {
    int h = DIGIT_HEIGHT + 2; /* 5 digits + 2 borders */
    if (!conf.hidedate) h += 2; /* +2 for date box */
    return h;
}

static int get_box_width(void) {
    return get_display_width() + 2; /* +2 for borders */
}

static void handle_resize(void) {
    int screen_h, screen_w;

    need_resize = 0;

    endwin();
    refresh();

    screen_h = LINES;
    screen_w = COLS;

    if (conf.center) {
        int cw = get_display_width();
        int ch = DIGIT_HEIGHT;
        if (!conf.hidedate) ch += 2;
        if (conf.box) { ch += 2; cw += 2; }
        conf.clock_x = (screen_w - cw) / 2;
        conf.clock_y = (screen_h - ch) / 2;
        if (conf.box) {
            /* Adjust inner position */
        }
    }
}

static void init_conf(void) {
    memset(&conf, 0, sizeof(conf));
    conf.color = 2; /* green */
    conf.delay = 1;
    conf.nsdelay = 0;
    conf.clock_x = 0;
    conf.clock_y = 0;
    conf.dir_x = 1;
    conf.dir_y = 1;
    strcpy(conf.format, "%F");
}

static void set_position(void) {
    int screen_h = LINES;
    int screen_w = COLS;
    int cw, ch;

    if (conf.seconds)
        cw = 52;
    else
        cw = 33; /* approximate */
    ch = DIGIT_HEIGHT;

    if (!conf.hidedate)
        ch += 2;

    if (conf.box) {
        ch += 2;
        cw += 2;
    }

    if (conf.center) {
        conf.clock_x = (screen_w - cw) / 2;
        conf.clock_y = (screen_h - ch) / 2;
        if (conf.clock_x < 0) conf.clock_x = 0;
        if (conf.clock_y < 0) conf.clock_y = 0;
    }
}

static void do_rebound(void) {
    int screen_h = LINES;
    int screen_w = COLS;
    int cw, ch;

    if (conf.seconds)
        cw = 52; /* total display width */
    else
        cw = 33;
    ch = DIGIT_HEIGHT + 2; /* +2 for date */

    if (conf.box) {
        cw += 2;
        ch += 2;
    }

    /* Move */
    conf.clock_x += conf.dir_x;
    conf.clock_y += conf.dir_y;

    /* Bounce off edges */
    if (conf.clock_x + cw >= screen_w || conf.clock_x <= 0) {
        if (conf.clock_x <= 0) conf.clock_x = 0;
        else conf.clock_x = screen_w - cw;
        conf.dir_x = -conf.dir_x;
    }

    if (conf.clock_y + ch >= screen_h || conf.clock_y <= 0) {
        if (conf.clock_y <= 0) conf.clock_y = 0;
        else conf.clock_y = screen_h - ch;
        conf.dir_y = -conf.dir_y;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    int h, m, s;
    time_t t;
    struct tm *tm_info;
    char date_str[256];
    int colon_visible = 1;
    struct timespec ts;
    int key;
    FILE *tty_file = NULL;

    init_conf();

    /* Parse arguments */
    while ((opt = getopt(argc, argv, "iuvsScbtrahDBxnC:f:d:a:T:")) != -1) {
        switch (opt) {
        case 'i':
            printf("TTY-Clock %s \xc2\xa9 by %s, %s\n", TTYCLOCK_VERSION, TTYCLOCK_AUTHOR, TTYCLOCK_MAIL);
            return 0;
        case 'v':
            printf("TTY-Clock %s \xc2\xa9 %s\n", TTYCLOCK_VERSION, TTYCLOCK_COPY);
            return 0;
        case 'h':
            usage();
            return 0;
        case 's':
            conf.seconds = 1;
            break;
        case 'S':
            conf.screensaver = 1;
            break;
        case 'x':
            conf.box = 1;
            break;
        case 'c':
            conf.center = 1;
            break;
        case 'b':
            conf.bold = 1;
            break;
        case 't':
            conf.twelve = 1;
            break;
        case 'u':
            conf.utc = 1;
            break;
        case 'r':
            conf.rebound = 1;
            break;
        case 'n':
            conf.noquit = 1;
            break;
        case 'D':
            conf.hidedate = 1;
            break;
        case 'B':
            conf.blink = 1;
            break;
        case 'C':
            conf.color = atoi(optarg);
            if (conf.color < 0 || conf.color > 7)
                conf.color = 2;
            break;
        case 'f':
            strncpy(conf.format, optarg, sizeof(conf.format) - 1);
            break;
        case 'd':
            conf.delay = atoi(optarg);
            break;
        case 'a':
            conf.nsdelay = atoi(optarg);
            break;
        case 'T':
            strncpy(conf.tty, optarg, sizeof(conf.tty) - 1);
            break;
        default:
            break;
        }
    }

    /* Open TTY if specified */
    if (conf.tty[0]) {
        tty_file = fopen(conf.tty, "r+");
        if (!tty_file) {
            fprintf(stderr, "tty-clock: cannot open %s: %s\n", conf.tty, strerror(errno));
            return 1;
        }
        /* Redirect to the TTY */
        if (freopen(conf.tty, "r+", stdin) == NULL ||
            freopen(conf.tty, "r+", stdout) == NULL) {
            fprintf(stderr, "tty-clock: cannot open %s: %s\n", conf.tty, strerror(errno));
            return 1;
        }
    }

    /* Initialize ncurses */
    initscr();
    noecho();
    cbreak();
    curs_set(0);

    if (has_colors()) {
        start_color();
        use_default_colors();
        /* Color pair 1: clock color */
        init_pair(1, -1, conf.color);
        /* Color pair 2: date color (foreground only) */
        init_pair(2, conf.color, -1);
        /* Color pair 3: box color (same as date) */
        init_pair(3, conf.color, -1);
    }

    keypad(stdscr, 1);

    /* Setup signals */
    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);
    signal(SIGWINCH, signal_handler);

    /* Set initial position */
    set_position();

    /* Main loop */
    while (running) {
        /* Handle resize */
        if (need_resize) {
            handle_resize();
            set_position();
            clear();
            refresh();
        }

        /* Get current time */
        time(&t);
        if (conf.utc)
            tm_info = gmtime(&t);
        else
            tm_info = localtime(&t);

        h = tm_info->tm_hour;
        m = tm_info->tm_min;
        s = tm_info->tm_sec;

        if (conf.twelve) {
            if (h == 0)
                h = 12;
            else if (h > 12)
                h -= 12;
        }

        strftime(date_str, sizeof(date_str), conf.format, tm_info);

        /* Blink colon */
        if (conf.blink)
            colon_visible = (s % 2 == 0) ? 1 : 0;
        else
            colon_visible = 1;

        /* Rebound */
        if (conf.rebound)
            do_rebound();

        /* Clear and redraw */
        clear();

        int draw_x = conf.clock_x;
        int draw_y = conf.clock_y;

        if (conf.box) {
            /* Draw box around the clock */
            int box_w = get_display_width() + 2;
            int box_h = DIGIT_HEIGHT + 2;
            if (!conf.hidedate) box_h += 0; /* date is outside box */

            wattron(stdscr, COLOR_PAIR(3));
            /* Draw box using ACS characters */
            int bx = draw_x;
            int by = draw_y;

            /* Top border */
            mvaddch(by, bx, 'l');
            int i;
            for (i = 1; i < box_w - 1; i++)
                mvaddch(by, bx + i, 'q');
            mvaddch(by, bx + box_w - 1, 'k');

            /* Sides */
            for (i = 1; i <= DIGIT_HEIGHT; i++) {
                mvaddch(by + i, bx, 'x');
                mvaddch(by + i, bx + box_w - 1, 'x');
            }

            /* Bottom border */
            mvaddch(by + DIGIT_HEIGHT + 1, bx, 'm');
            for (i = 1; i < box_w - 1; i++)
                mvaddch(by + DIGIT_HEIGHT + 1, bx + i, 'q');
            mvaddch(by + DIGIT_HEIGHT + 1, bx + box_w - 1, 'j');

            wattroff(stdscr, COLOR_PAIR(3));

            /* Clock content is inside box */
            draw_y++;
            draw_x++;
        }

        /* Draw clock digits */
        draw_clock(stdscr, draw_y, draw_x, h, m, s, colon_visible);

        if (conf.box)
            draw_x--;

        /* Draw date */
        if (!conf.hidedate) {
            int date_row = draw_y + DIGIT_HEIGHT;
            if (conf.box) {
                date_row++;
                draw_x++;
            }
            int date_len = strlen(date_str);
            int total_w = get_display_width();

            /* With box: date appears below the box with its own sub-box */
            if (conf.box) {
                int date_x = draw_x + (total_w - date_len) / 2;
                int date_subbox_x = date_x - 1;

                /* Sub-box for date */
                wattron(stdscr, COLOR_PAIR(3));
                mvaddch(date_row, date_subbox_x, 'x');
                wmove(stdscr, date_row, date_subbox_x + 1);
                wattron(stdscr, COLOR_PAIR(2));
                waddstr(stdscr, date_str);
                wattroff(stdscr, COLOR_PAIR(2));
                wattron(stdscr, COLOR_PAIR(3));
                mvaddch(date_row, date_subbox_x + 1 + date_len, 'x');

                mvaddch(date_row + 1, date_subbox_x, 'm');
                for (int i = 0; i < date_len; i++)
                    mvaddch(date_row + 1, date_subbox_x + 1 + i, 'q');
                mvaddch(date_row + 1, date_subbox_x + 1 + date_len, 'j');
                wattroff(stdscr, COLOR_PAIR(3));
            } else {
                /* No box: just the date string */
                int date_x = draw_x + (total_w - date_len) / 2;
                wmove(stdscr, date_row, date_x);
                wattron(stdscr, COLOR_PAIR(2));
                waddstr(stdscr, date_str);
                wattroff(stdscr, COLOR_PAIR(2));
            }
        }

        refresh();

        /* Non-blocking key read */
        wtimeout(stdscr, 0);
        key = wgetch(stdscr);

        if (key != ERR) {
            if (conf.screensaver) {
                if (!conf.noquit)
                    running = 0;
            } else {
                /* Process key */
                switch (key) {
                case 'q': case 'Q':
                    if (!conf.noquit)
                        running = 0;
                    break;
                case 'k': case 'K': case KEY_UP:
                    if (!conf.center) conf.clock_y--;
                    break;
                case 'j': case 'J': case KEY_DOWN:
                    if (!conf.center) conf.clock_y++;
                    break;
                case 'h': case 'H': case KEY_LEFT:
                    if (!conf.center) conf.clock_x--;
                    break;
                case 'l': case 'L': case KEY_RIGHT:
                    if (!conf.center) conf.clock_x++;
                    break;
                case 'c': case 'C':
                    conf.center = !conf.center;
                    if (conf.center) set_position();
                    break;
                case 'r': case 'R':
                    conf.rebound = !conf.rebound;
                    break;
                case 's': case 'S':
                    conf.seconds = !conf.seconds;
                    break;
                case 't': case 'T':
                    conf.twelve = !conf.twelve;
                    break;
                case 'b': case 'B':
                    conf.bold = !conf.bold;
                    break;
                case 'x': case 'X':
                    conf.box = !conf.box;
                    break;
                case '0': case '1': case '2': case '3':
                case '4': case '5': case '6': case '7':
                    conf.color = key - '0';
                    init_pair(1, -1, conf.color);
                    init_pair(2, conf.color, -1);
                    init_pair(3, conf.color, -1);
                    break;
                }
            }
        }

        /* Sleep */
        ts.tv_sec = conf.delay;
        ts.tv_nsec = conf.nsdelay;
        nanosleep(&ts, NULL);
    }

    endwin();

    if (tty_file)
        fclose(tty_file);

    return 0;
}
CEOF

