    need_resize = 0;

    endwin();
    refresh();

    screen_h = LINES;
    screen_w = COLS;

    if (conf.center) {
        int cw = get_display_width();
        int ch = DIGIT_HEIGHT;
        if (!conf.hidedate) ch += 2;
        if (conf.box) { ch += 2; cw += 2; }
        conf.clock_x = (screen_w - cw) / 2;
        conf.clock_y = (screen_h - ch) / 2;
        if (conf.box) {
            /* Adjust inner position */
        }
    }
}

static void init_conf(void) {
    memset(&conf, 0, sizeof(conf));
    conf.color = 2; /* green */
    conf.delay = 1;
    conf.nsdelay = 0;
    conf.clock_x = 0;
    conf.clock_y = 0;
    conf.dir_x = 1;
    conf.dir_y = 1;
    strcpy(conf.format, "%F");
}

static void set_position(void) {
    int screen_h = LINES;
    int screen_w = COLS;
    int cw, ch;

    if (conf.seconds)
        cw = 52;
    else
        cw = 33; /* approximate */
    ch = DIGIT_HEIGHT;

    if (!conf.hidedate)
        ch += 2;

    if (conf.box) {
        ch += 2;
        cw += 2;
    }

    if (conf.center) {
        conf.clock_x = (screen_w - cw) / 2;
        conf.clock_y = (screen_h - ch) / 2;
        if (conf.clock_x < 0) conf.clock_x = 0;
        if (conf.clock_y < 0) conf.clock_y = 0;
    }
}

static void do_rebound(void) {
    int screen_h = LINES;
    int screen_w = COLS;
    int cw, ch;

    if (conf.seconds)
        cw = 52; /* total display width */
    else
        cw = 33;
    ch = DIGIT_HEIGHT + 2; /* +2 for date */

    if (conf.box) {
        cw += 2;
        ch += 2;
    }

    /* Move */
    conf.clock_x += conf.dir_x;
    conf.clock_y += conf.dir_y;

    /* Bounce off edges */
    if (conf.clock_x + cw >= screen_w || conf.clock_x <= 0) {
        if (conf.clock_x <= 0) conf.clock_x = 0;
        else conf.clock_x = screen_w - cw;
        conf.dir_x = -conf.dir_x;
    }

    if (conf.clock_y + ch >= screen_h || conf.clock_y <= 0) {
        if (conf.clock_y <= 0) conf.clock_y = 0;
        else conf.clock_y = screen_h - ch;
        conf.dir_y = -conf.dir_y;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    int h, m, s;
    time_t t;
    struct tm *tm_info;
    char date_str[256];
    int colon_visible = 1;
    struct timespec ts;
    int key;
    FILE *tty_file = NULL;

    init_conf();

    /* Parse arguments */
    while ((opt = getopt(argc, argv, "iuvsScbtrahDBxnC:f:d:a:T:")) != -1) {
        switch (opt) {
        case 'i':
            printf("TTY-Clock %s \xc2\xa9 by %s, %s\n", TTYCLOCK_VERSION, TTYCLOCK_AUTHOR, TTYCLOCK_MAIL);
            return 0;
        case 'v':
            printf("TTY-Clock %s \xc2\xa9 %s\n", TTYCLOCK_VERSION, TTYCLOCK_COPY);
            return 0;
        case 'h':
            usage();
            return 0;
        case 's':
            conf.seconds = 1;
            break;
        case 'S':
            conf.screensaver = 1;
            break;
        case 'x':
            conf.box = 1;
            break;
        case 'c':
            conf.center = 1;
            break;
        case 'b':
            conf.bold = 1;
            break;
        case 't':
            conf.twelve = 1;
            break;
        case 'u':
            conf.utc = 1;
            break;
        case 'r':
            conf.rebound = 1;
            break;
        case 'n':
            conf.noquit = 1;
            break;
        case 'D':
            conf.hidedate = 1;
            break;
        case 'B':
            conf.blink = 1;
            break;
        case 'C':
            conf.color = atoi(optarg);
            if (conf.color < 0 || conf.color > 7)
                conf.color = 2;
            break;
        case 'f':
            strncpy(conf.format, optarg, sizeof(conf.format) - 1);
            break;
        case 'd':
            conf.delay = atoi(optarg);
            break;
        case 'a':
            conf.nsdelay = atoi(optarg);
            break;
        case 'T':
            strncpy(conf.tty, optarg, sizeof(conf.tty) - 1);
            break;
        default:
            break;
        }
    }

    /* Open TTY if specified */
    if (conf.tty[0]) {
        tty_file = fopen(conf.tty, "r+");
        if (!tty_file) {
            fprintf(stderr, "tty-clock: cannot open %s: %s\n", conf.tty, strerror(errno));
            return 1;
        }
        /* Redirect to the TTY */
        if (freopen(conf.tty, "r+", stdin) == NULL ||
            freopen(conf.tty, "r+", stdout) == NULL) {
            fprintf(stderr, "tty-clock: cannot open %s: %s\n", conf.tty, strerror(errno));
            return 1;
        }
    }

    /* Initialize ncurses */
    initscr();
    noecho();
    cbreak();
    curs_set(0);

    if (has_colors()) {
        start_color();
        use_default_colors();
        /* Color pair 1: clock color */
        init_pair(1, -1, conf.color);
        /* Color pair 2: date color (foreground only) */
        init_pair(2, conf.color, -1);
        /* Color pair 3: box color (same as date) */
        init_pair(3, conf.color, -1);
    }

    keypad(stdscr, 1);

    /* Setup signals */
    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);
    signal(SIGWINCH, signal_handler);

    /* Set initial position */
    set_position();

    /* Main loop */
    while (running) {
        /* Handle resize */
        if (need_resize) {
