/* Draw a single digit at the given screen position */
static void draw_digit(int d, int row, int col) {
    int r, p;

    if (d < 0 || d > 9) return;

    for (r = 0; r < DIGIT_HEIGHT; r++) {
        for (p = 0; p < 3; p++) {
            wmove(stdscr, row + r, col + p * 2);
            if (digits[d][r][p]) {
                if (conf.bold) wattron(stdscr, A_BOLD);
                wattron(stdscr, COLOR_PAIR(1));
                waddstr(stdscr, "  ");
                wattroff(stdscr, COLOR_PAIR(1));
