static void draw_colon(int row, int col, int visible) {
    int r;

    for (r = 0; r < DIGIT_HEIGHT; r++) {
        /* Left blank */
        wmove(stdscr, row + r, col);
        waddstr(stdscr, "  ");

        /* Center: dot at rows 1 and 3 */
        wmove(stdscr, row + r, col + 2);
        if (visible && (r == 1 || r == 3)) {
            if (conf.bold) wattron(stdscr, A_BOLD);
            wattron(stdscr, COLOR_PAIR(1));
            waddstr(stdscr, "  ");
            wattroff(stdscr, COLOR_PAIR(1));
            if (conf.bold) wattroff(stdscr, A_BOLD);
        } else {
            waddstr(stdscr, "  ");
        }

        /* Right blank */
        wmove(stdscr, row + r, col + 4);
        waddstr(stdscr, "  ");
    }
