    conf.clock_x += conf.dir_x;
    conf.clock_y += conf.dir_y;

    if (conf.clock_x + cw >= screen_w) {
        conf.clock_x = screen_w - cw;
        conf.dir_x = -conf.dir_x;
    }
    if (conf.clock_x <= 0) {
        conf.clock_x = 0;
        conf.dir_x = -conf.dir_x;
