    if (conf.clock_y + ch >= screen_h) {
        conf.clock_y = screen_h - ch;
        conf.dir_y = -conf.dir_y;
    }
    if (conf.clock_y <= 0) {
        conf.clock_y = 0;
        conf.dir_y = -conf.dir_y;
