    struct tm *tm_info;
    char date_str[256];
    int colon_visible = 1;
    struct timespec ts;
    int key;

    /* Initialize configuration with defaults */
    memset(&conf, 0, sizeof(conf));
    conf.color = 2; /* green */
    conf.delay = 1;
    conf.nsdelay = 0;
    conf.clock_x = 0;
    conf.clock_y = 0;
    conf.dir_x = 1;
    conf.dir_y = 1;
    strcpy(conf.format, "%F");

    /* Parse command line arguments */
    while ((opt = getopt(argc, argv, "iuvsScbtrahDBxnC:f:d:a:T:")) != -1) {
        switch (opt) {
        case 'i':
            printf("TTY-Clock %s \xc2\xa9 by %s, %s\n",
                   TTYCLOCK_VERSION, TTYCLOCK_AUTHOR, TTYCLOCK_MAIL);
            return 0;
        case 'v':
            printf("TTY-Clock %s \xc2\xa9 %s\n", TTYCLOCK_VERSION, TTYCLOCK_COPY);
            return 0;
        case 'h':
            usage();
            return 0;
        case 's': conf.seconds = 1; break;
        case 'S': conf.screensaver = 1; break;
        case 'x': conf.box = 1; break;
        case 'c': conf.center = 1; break;
        case 'b': conf.bold = 1; break;
        case 't': conf.twelve = 1; break;
        case 'u': conf.utc = 1; break;
        case 'r': conf.rebound = 1; break;
        case 'n': conf.noquit = 1; break;
        case 'D': conf.hidedate = 1; break;
        case 'B': conf.blink = 1; break;
        case 'C':
            conf.color = atoi(optarg);
            if (conf.color < 0 || conf.color > 7) conf.color = 2;
            break;
        case 'f':
            strncpy(conf.format, optarg, sizeof(conf.format) - 1);
            break;
        case 'd': conf.delay = atoi(optarg); break;
        case 'a': conf.nsdelay = atoi(optarg); break;
        case 'T':
            strncpy(conf.tty, optarg, sizeof(conf.tty) - 1);
            break;
        default: break;
        }
    }

    /* Open TTY if specified */
    if (conf.tty[0]) {
        if (freopen(conf.tty, "r+", stdin) == NULL ||
            freopen(conf.tty, "r+", stdout) == NULL) {
            fprintf(stderr, "tty-clock: cannot open %s: %s\n", conf.tty, strerror(errno));
            return 1;
        }
    }

    /* Initialize ncurses */
    initscr();
    noecho();
    cbreak();
    curs_set(0);

    if (has_colors()) {
        start_color();
        use_default_colors();
        update_color_pairs();
    }

    keypad(stdscr, 1);

    /* Setup signal handlers */
    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);
    signal(SIGWINCH, signal_handler);

    /* Set initial position */
    set_position();

    /* Main loop */
    while (running) {
        /* Handle terminal resize */
        if (need_resize) {
            need_resize = 0;
            endwin();
            refresh();
            set_position();
            clear();
            refresh();
        }

        /* Get current time */
        time(&t);
        if (conf.utc)
            tm_info = gmtime(&t);
        else
            tm_info = localtime(&t);

        h = tm_info->tm_hour;
        m = tm_info->tm_min;
        s = tm_info->tm_sec;

        /* Convert to 12-hour format if requested */
        if (conf.twelve) {
            if (h == 0)
                h = 12;
            else if (h > 12)
                h -= 12;
        }

        /* Format date string */
        strftime(date_str, sizeof(date_str), conf.format, tm_info);

