        if (conf.box) {
            int box_w = get_display_width() + 2;
            int i;

            wattron(stdscr, COLOR_PAIR(3));

            /* Top border */
            mvaddch(draw_y, draw_x, 'l');
            for (i = 1; i < box_w - 1; i++)
                mvaddch(draw_y, draw_x + i, 'q');
            mvaddch(draw_y, draw_x + box_w - 1, 'k');

            /* Side borders */
            for (i = 1; i <= DIGIT_HEIGHT; i++) {
                mvaddch(draw_y + i, draw_x, 'x');
                mvaddch(draw_y + i, draw_x + box_w - 1, 'x');
            }

            /* Bottom border */
            mvaddch(draw_y + DIGIT_HEIGHT + 1, draw_x, 'm');
            for (i = 1; i < box_w - 1; i++)
                mvaddch(draw_y + DIGIT_HEIGHT + 1, draw_x + i, 'q');
            mvaddch(draw_y + DIGIT_HEIGHT + 1, draw_x + box_w - 1, 'j');

            wattroff(stdscr, COLOR_PAIR(3));

            /* Clock digits go inside the box */
            inner_x = draw_x + 1;
            inner_y = draw_y + 1;
        }

        /* Draw hours: H1 at offset 1, H2 at offset 1+6+1=8 */
        draw_digit(h / 10, inner_y, inner_x + 1);
        draw_digit(h % 10, inner_y, inner_x + 1 + DIGIT_WIDTH + GAP_WIDTH);

        /* Draw colon between hours and minutes: at offset 1+6+1+6=14 */
        draw_colon(inner_y, inner_x + 1 + DIGIT_WIDTH * 2 + GAP_WIDTH, colon_visible);

        /* Draw minutes: M1 at offset 1+6+1+6+6=20, M2 at offset 1+6+1+6+6+6+1=27 */
        draw_digit(m / 10, inner_y, inner_x + 1 + DIGIT_WIDTH * 2 + GAP_WIDTH + COLON_WIDTH);
        draw_digit(m % 10, inner_y, inner_x + 1 + DIGIT_WIDTH * 3 + GAP_WIDTH * 2 + COLON_WIDTH);

        if (conf.seconds) {
            /* Draw colon between minutes and seconds: at offset 1+6+1+6+6+6+1+6=33 */
            draw_colon(inner_y, inner_x + 1 + DIGIT_WIDTH * 4 + GAP_WIDTH * 2 + COLON_WIDTH, colon_visible);

            /* Draw seconds: S1 at offset 39, S2 at offset 46 */
            draw_digit(s / 10, inner_y, inner_x + 1 + DIGIT_WIDTH * 4 + GAP_WIDTH * 2 + COLON_WIDTH * 2);
            draw_digit(s % 10, inner_y, inner_x + 1 + DIGIT_WIDTH * 5 + GAP_WIDTH * 3 + COLON_WIDTH * 2);
        }

        /* Draw date if not hidden */
        if (!conf.hidedate) {
            int date_len = strlen(date_str);
            int total_w = get_display_width();
            int date_row = inner_y + DIGIT_HEIGHT;
            int date_x;

            if (conf.box) {
                /* Date box appears below the main box */
                date_row = draw_y + DIGIT_HEIGHT + 2;

                /* Center date under the display (taking box offset into account) */
                date_x = inner_x + (total_w - date_len) / 2;

                /* Draw date sub-box: x_date_str_x */
                wattron(stdscr, COLOR_PAIR(3));
                mvaddch(date_row, date_x - 1, 'x');
                wattron(stdscr, COLOR_PAIR(2));
                wmove(stdscr, date_row, date_x);
                waddstr(stdscr, date_str);
                wattroff(stdscr, COLOR_PAIR(2));
                wattron(stdscr, COLOR_PAIR(3));
                mvaddch(date_row, date_x + date_len, 'x');

                /* Bottom of date sub-box */
                mvaddch(date_row + 1, date_x - 1, 'm');
                int i;
                for (i = 0; i < date_len; i++)
                    mvaddch(date_row + 1, date_x + i, 'q');
                mvaddch(date_row + 1, date_x + date_len, 'j');
                wattroff(stdscr, COLOR_PAIR(3));
            } else {
                /* No box: just date string centered below clock */
                date_x = inner_x + (total_w - date_len) / 2;
                wmove(stdscr, date_row, date_x);
                wattron(stdscr, COLOR_PAIR(2));
                waddstr(stdscr, date_str);
                wattroff(stdscr, COLOR_PAIR(2));
            }
        }

        refresh();

        /* Non-blocking key check */
        wtimeout(stdscr, 0);
        key = wgetch(stdscr);

        if (key != ERR) {
            if (conf.screensaver) {
                if (!conf.noquit)
                    running = 0;
            } else {
                switch (key) {
                case 'q': case 'Q':
                    if (!conf.noquit) running = 0;
                    break;
                case 'k': case 'K': case KEY_UP:
                    if (!conf.center) conf.clock_y--;
                    break;
                case 'j': case 'J': case KEY_DOWN:
                    if (!conf.center) conf.clock_y++;
                    break;
                case 'h': case 'H': case KEY_LEFT:
                    if (!conf.center) conf.clock_x--;
                    break;
                case 'l': case 'L': case KEY_RIGHT:
                    if (!conf.center) conf.clock_x++;
                    break;
                case 'c': case 'C':
                    conf.center = !conf.center;
                    if (conf.center) set_position();
                    break;
                case 'r': case 'R':
                    conf.rebound = !conf.rebound;
                    break;
                case 's': case 'S':
                    conf.seconds = !conf.seconds;
                    break;
                case 't': case 'T':
                    conf.twelve = !conf.twelve;
                    break;
                case 'b': case 'B':
                    conf.bold = !conf.bold;
                    break;
                case 'x': case 'X':
                    conf.box = !conf.box;
                    break;
                case '0': case '1': case '2': case '3':
                case '4': case '5': case '6': case '7':
                    conf.color = key - '0';
                    update_color_pairs();
