    int       blink;        /* blinking colon */
    int       noquit;       /* don't quit on keypress */
    char      format[128];  /* date format string (strftime) */
    int       delay;        /* delay in seconds between redraws */
    int       nsdelay;      /* additional nanosecond delay */
    char      tty[256];     /* TTY device path */
    int       clock_x;      /* clock x position */
    int       clock_y;      /* clock y position */
    int       dir_x;        /* rebound x direction (+1 or -1) */
    int       dir_y;        /* rebound y direction (+1 or -1) */
} clock_config;

static clock_config conf;
static volatile int running = 1;
static volatile int need_resize = 0;

#define TTYCLOCK_VERSION "2"
#define TTYCLOCK_COPY    "devel version"
#define TTYCLOCK_AUTHOR  "Martin Duquesnoy (xorg62@gmail.com)"
#define TTYCLOCK_MAIL    "grey@greytheory.net"

static void usage(void) {
    printf("usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty] \n"
           "    -s            Show seconds                                   \n"
           "    -S            Screensaver mode                               \n"
           "    -x            Show box                                       \n"
           "    -c            Set the clock at the center of the terminal    \n"
           "    -C [0-7]      Set the clock color                            \n"
           "    -b            Use bold colors                                \n"
           "    -t            Set the hour in 12h format                     \n"
           "    -u            Use UTC time                                   \n"
           "    -T tty        Display the clock on the specified terminal    \n"
           "    -r            Do rebound the clock                           \n"
           "    -f format     Set the date format                            \n"
           "    -n            Don't quit on keypress                         \n"
           "    -v            Show tty-clock version                         \n"
           "    -i            Show some info about tty-clock                 \n"
           "    -h            Show this page                                 \n"
           "    -D            Hide date                                      \n"
           "    -B            Enable blinking colon                          \n"
           "    -d delay      Set the delay between two redraws of the clock. Default 1s. \n"
           "    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns.\n");
}

static void signal_handler(int sig) {
    switch(sig) {
    case SIGTERM:
    case SIGINT:
        running = 0;
        break;
    case SIGWINCH:
        need_resize = 1;
        break;
    default:
        break;
    }
}

/* Get total display width */
static int get_display_width(void) {
    /* bg(1) + D1(6) + gap(1) + D2(6) + colon(6) + D3(6) + gap(1) + D4(6) [+ colon(6) + D5(6) + gap(1) + D6(6)] */
    if (conf.seconds)
        return 1 + DIGIT_WIDTH + GAP_WIDTH + DIGIT_WIDTH + COLON_WIDTH + 
               DIGIT_WIDTH + GAP_WIDTH + DIGIT_WIDTH + COLON_WIDTH + 
               DIGIT_WIDTH + GAP_WIDTH + DIGIT_WIDTH;
    else
        return 1 + DIGIT_WIDTH + GAP_WIDTH + DIGIT_WIDTH + COLON_WIDTH + 
               DIGIT_WIDTH + GAP_WIDTH + DIGIT_WIDTH;
}

/* Draw a single digit at the given screen position */
static void draw_digit(int d, int row, int col) {
    int r, p;

    if (d < 0 || d > 9) return;

    for (r = 0; r < DIGIT_HEIGHT; r++) {
        for (p = 0; p < 3; p++) {
            wmove(stdscr, row + r, col + p * 2);
            if (digits[d][r][p]) {
                if (conf.bold) wattron(stdscr, A_BOLD);
                wattron(stdscr, COLOR_PAIR(1));
                waddstr(stdscr, "  ");
                wattroff(stdscr, COLOR_PAIR(1));
                if (conf.bold) wattroff(stdscr, A_BOLD);
            } else {
                waddstr(stdscr, "  ");
            }
        }
    }
}

/* Draw colon: [blank(2)][dot(2)][blank(2)] = 6 chars total */
/* Dot is visible at rows 1 and 3 of the 5-row display */
static void draw_colon(int row, int col, int visible) {
    int r;

    for (r = 0; r < DIGIT_HEIGHT; r++) {
        /* Left blank */
        wmove(stdscr, row + r, col);
        waddstr(stdscr, "  ");

        /* Center: dot at rows 1 and 3 */
        wmove(stdscr, row + r, col + 2);
        if (visible && (r == 1 || r == 3)) {
            if (conf.bold) wattron(stdscr, A_BOLD);
            wattron(stdscr, COLOR_PAIR(1));
            waddstr(stdscr, "  ");
            wattroff(stdscr, COLOR_PAIR(1));
            if (conf.bold) wattroff(stdscr, A_BOLD);
        } else {
            waddstr(stdscr, "  ");
        }

        /* Right blank */
        wmove(stdscr, row + r, col + 4);
        waddstr(stdscr, "  ");
    }
}

/* Update color pairs based on conf.color */
static void update_color_pairs(void) {
    init_pair(1, -1, conf.color);      /* clock background color */
    init_pair(2, conf.color, -1);      /* date foreground color */
    init_pair(3, conf.color, -1);      /* box/frame color */
}

/* Set initial position */
static void set_position(void) {
    int screen_h = LINES;
    int screen_w = COLS;
    int cw, ch;

    cw = get_display_width();
    ch = DIGIT_HEIGHT;
    if (!conf.hidedate) ch += 2;
    if (conf.box) { ch += 2; cw += 2; }

    if (conf.center) {
        conf.clock_x = (screen_w - cw) / 2;
        conf.clock_y = (screen_h - ch) / 2;
        if (conf.clock_x < 0) conf.clock_x = 0;
        if (conf.clock_y < 0) conf.clock_y = 0;
    }
}

/* Move clock for rebound effect */
static void do_rebound(void) {
    int screen_h = LINES;
    int screen_w = COLS;
    int cw, ch;

    cw = get_display_width();
    ch = DIGIT_HEIGHT;
    if (!conf.hidedate) ch += 2;
    if (conf.box) { ch += 2; cw += 2; }

    conf.clock_x += conf.dir_x;
    conf.clock_y += conf.dir_y;

    if (conf.clock_x + cw >= screen_w) {
        conf.clock_x = screen_w - cw;
        conf.dir_x = -conf.dir_x;
    }
    if (conf.clock_x <= 0) {
        conf.clock_x = 0;
        conf.dir_x = -conf.dir_x;
    }

    if (conf.clock_y + ch >= screen_h) {
        conf.clock_y = screen_h - ch;
        conf.dir_y = -conf.dir_y;
    }
    if (conf.clock_y <= 0) {
        conf.clock_y = 0;
        conf.dir_y = -conf.dir_y;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    int h, m, s;
    time_t t;
    struct tm *tm_info;
    char date_str[256];
    int colon_visible = 1;
    struct timespec ts;
    int key;

    /* Initialize configuration with defaults */
    memset(&conf, 0, sizeof(conf));
    conf.color = 2; /* green */
    conf.delay = 1;
    conf.nsdelay = 0;
    conf.clock_x = 0;
    conf.clock_y = 0;
    conf.dir_x = 1;
    conf.dir_y = 1;
    strcpy(conf.format, "%F");

    /* Parse command line arguments */
    while ((opt = getopt(argc, argv, "iuvsScbtrahDBxnC:f:d:a:T:")) != -1) {
        switch (opt) {
        case 'i':
            printf("TTY-Clock %s \xc2\xa9 by %s, %s\n",
                   TTYCLOCK_VERSION, TTYCLOCK_AUTHOR, TTYCLOCK_MAIL);
            return 0;
        case 'v':
            printf("TTY-Clock %s \xc2\xa9 %s\n", TTYCLOCK_VERSION, TTYCLOCK_COPY);
            return 0;
        case 'h':
            usage();
            return 0;
        case 's': conf.seconds = 1; break;
        case 'S': conf.screensaver = 1; break;
        case 'x': conf.box = 1; break;
        case 'c': conf.center = 1; break;
        case 'b': conf.bold = 1; break;
        case 't': conf.twelve = 1; break;
        case 'u': conf.utc = 1; break;
        case 'r': conf.rebound = 1; break;
        case 'n': conf.noquit = 1; break;
        case 'D': conf.hidedate = 1; break;
        case 'B': conf.blink = 1; break;
        case 'C':
            conf.color = atoi(optarg);
            if (conf.color < 0 || conf.color > 7) conf.color = 2;
            break;
        case 'f':
            strncpy(conf.format, optarg, sizeof(conf.format) - 1);
            break;
        case 'd': conf.delay = atoi(optarg); break;
        case 'a': conf.nsdelay = atoi(optarg); break;
        case 'T':
            strncpy(conf.tty, optarg, sizeof(conf.tty) - 1);
            break;
        default: break;
        }
    }

    /* Open TTY if specified */
    if (conf.tty[0]) {
        if (freopen(conf.tty, "r+", stdin) == NULL ||
            freopen(conf.tty, "r+", stdout) == NULL) {
            fprintf(stderr, "tty-clock: cannot open %s: %s\n", conf.tty, strerror(errno));
            return 1;
        }
    }

    /* Initialize ncurses */
    initscr();
    noecho();
    cbreak();
    curs_set(0);

    if (has_colors()) {
        start_color();
        use_default_colors();
        update_color_pairs();
    }

    keypad(stdscr, 1);

    /* Setup signal handlers */
    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);
    signal(SIGWINCH, signal_handler);

    /* Set initial position */
    set_position();

    /* Main loop */
    while (running) {
        /* Handle terminal resize */
        if (need_resize) {
            need_resize = 0;
            endwin();
            refresh();
            set_position();
            clear();
            refresh();
        }

        /* Get current time */
        time(&t);
        if (conf.utc)
            tm_info = gmtime(&t);
        else
            tm_info = localtime(&t);

        h = tm_info->tm_hour;
        m = tm_info->tm_min;
        s = tm_info->tm_sec;

        /* Convert to 12-hour format if requested */
        if (conf.twelve) {
            if (h == 0)
                h = 12;
            else if (h > 12)
                h -= 12;
        }

        /* Format date string */
        strftime(date_str, sizeof(date_str), conf.format, tm_info);

        /* Handle blinking colon */
        if (conf.blink)
            colon_visible = (s % 2 == 0) ? 1 : 0;
        else
            colon_visible = 1;

        /* Handle rebound */
        if (conf.rebound)
            do_rebound();

        /* Clear screen */
        clear();

        int draw_x = conf.clock_x;
        int draw_y = conf.clock_y;
        int inner_x = draw_x;
        int inner_y = draw_y;

        /* Draw box if enabled */
        if (conf.box) {
            int box_w = get_display_width() + 2;
            int i;

            wattron(stdscr, COLOR_PAIR(3));

            /* Top border */
            mvaddch(draw_y, draw_x, 'l');
            for (i = 1; i < box_w - 1; i++)
                mvaddch(draw_y, draw_x + i, 'q');
            mvaddch(draw_y, draw_x + box_w - 1, 'k');

            /* Side borders */
            for (i = 1; i <= DIGIT_HEIGHT; i++) {
                mvaddch(draw_y + i, draw_x, 'x');
                mvaddch(draw_y + i, draw_x + box_w - 1, 'x');
            }

            /* Bottom border */
            mvaddch(draw_y + DIGIT_HEIGHT + 1, draw_x, 'm');
            for (i = 1; i < box_w - 1; i++)
                mvaddch(draw_y + DIGIT_HEIGHT + 1, draw_x + i, 'q');
            mvaddch(draw_y + DIGIT_HEIGHT + 1, draw_x + box_w - 1, 'j');

            wattroff(stdscr, COLOR_PAIR(3));

            /* Clock digits go inside the box */
            inner_x = draw_x + 1;
            inner_y = draw_y + 1;
        }

        /* Draw hours: H1 at offset 1, H2 at offset 1+6+1=8 */
        draw_digit(h / 10, inner_y, inner_x + 1);
        draw_digit(h % 10, inner_y, inner_x + 1 + DIGIT_WIDTH + GAP_WIDTH);

        /* Draw colon between hours and minutes: at offset 1+6+1+6=14 */
        draw_colon(inner_y, inner_x + 1 + DIGIT_WIDTH * 2 + GAP_WIDTH, colon_visible);

        /* Draw minutes: M1 at offset 1+6+1+6+6=20, M2 at offset 1+6+1+6+6+6+1=27 */
        draw_digit(m / 10, inner_y, inner_x + 1 + DIGIT_WIDTH * 2 + GAP_WIDTH + COLON_WIDTH);
        draw_digit(m % 10, inner_y, inner_x + 1 + DIGIT_WIDTH * 3 + GAP_WIDTH * 2 + COLON_WIDTH);

        if (conf.seconds) {
            /* Draw colon between minutes and seconds: at offset 1+6+1+6+6+6+1+6=33 */
            draw_colon(inner_y, inner_x + 1 + DIGIT_WIDTH * 4 + GAP_WIDTH * 2 + COLON_WIDTH, colon_visible);

            /* Draw seconds: S1 at offset 39, S2 at offset 46 */
            draw_digit(s / 10, inner_y, inner_x + 1 + DIGIT_WIDTH * 4 + GAP_WIDTH * 2 + COLON_WIDTH * 2);
            draw_digit(s % 10, inner_y, inner_x + 1 + DIGIT_WIDTH * 5 + GAP_WIDTH * 3 + COLON_WIDTH * 2);
        }

        /* Draw date if not hidden */
        if (!conf.hidedate) {
            int date_len = strlen(date_str);
            int total_w = get_display_width();
            int date_row = inner_y + DIGIT_HEIGHT;
            int date_x;

            if (conf.box) {
                /* Date box appears below the main box */
                date_row = draw_y + DIGIT_HEIGHT + 2;

                /* Center date under the display (taking box offset into account) */
                date_x = inner_x + (total_w - date_len) / 2;

                /* Draw date sub-box: x_date_str_x */
                wattron(stdscr, COLOR_PAIR(3));
                mvaddch(date_row, date_x - 1, 'x');
                wattron(stdscr, COLOR_PAIR(2));
                wmove(stdscr, date_row, date_x);
                waddstr(stdscr, date_str);
                wattroff(stdscr, COLOR_PAIR(2));
                wattron(stdscr, COLOR_PAIR(3));
                mvaddch(date_row, date_x + date_len, 'x');

                /* Bottom of date sub-box */
                mvaddch(date_row + 1, date_x - 1, 'm');
                int i;
                for (i = 0; i < date_len; i++)
                    mvaddch(date_row + 1, date_x + i, 'q');
                mvaddch(date_row + 1, date_x + date_len, 'j');
                wattroff(stdscr, COLOR_PAIR(3));
            } else {
                /* No box: just date string centered below clock */
                date_x = inner_x + (total_w - date_len) / 2;
                wmove(stdscr, date_row, date_x);
                wattron(stdscr, COLOR_PAIR(2));
                waddstr(stdscr, date_str);
                wattroff(stdscr, COLOR_PAIR(2));
            }
        }

        refresh();

        /* Non-blocking key check */
        wtimeout(stdscr, 0);
        key = wgetch(stdscr);

        if (key != ERR) {
            if (conf.screensaver) {
                if (!conf.noquit)
                    running = 0;
            } else {
                switch (key) {
                case 'q': case 'Q':
                    if (!conf.noquit) running = 0;
                    break;
                case 'k': case 'K': case KEY_UP:
                    if (!conf.center) conf.clock_y--;
                    break;
                case 'j': case 'J': case KEY_DOWN:
                    if (!conf.center) conf.clock_y++;
                    break;
                case 'h': case 'H': case KEY_LEFT:
                    if (!conf.center) conf.clock_x--;
                    break;
                case 'l': case 'L': case KEY_RIGHT:
                    if (!conf.center) conf.clock_x++;
                    break;
                case 'c': case 'C':
                    conf.center = !conf.center;
                    if (conf.center) set_position();
                    break;
                case 'r': case 'R':
                    conf.rebound = !conf.rebound;
                    break;
                case 's': case 'S':
                    conf.seconds = !conf.seconds;
                    break;
                case 't': case 'T':
                    conf.twelve = !conf.twelve;
                    break;
                case 'b': case 'B':
                    conf.bold = !conf.bold;
                    break;
                case 'x': case 'X':
                    conf.box = !conf.box;
                    break;
                case '0': case '1': case '2': case '3':
                case '4': case '5': case '6': case '7':
                    conf.color = key - '0';
                    update_color_pairs();
                    break;
                }
            }
        }

        /* Wait for next redraw */
        ts.tv_sec = conf.delay;
        ts.tv_nsec = conf.nsdelay;
        nanosleep(&ts, NULL);
    }

    endwin();
    return 0;
}
CEOF

cd /workspace && ./compile.sh 2>&1 | grep -v "warning"
echo "Compile exit: $?"
